import { Component } from '@angular/core';
import { MisComprasService } from 'src/app/services/mis-compras.service';
import { UsuarioService } from 'src/app/services/usuario.service';

@Component({
  selector: 'app-ej-productos',
  templateUrl: './ej-productos.component.html',
  styleUrls: ['./ej-productos.component.css']
})
export class EjProductosComponent{

  primerProducto: string = "";
  ultimoProducto: string = "";

  constructor(private misComprasService: MisComprasService, private usuarioService: UsuarioService) { }

    recogerProductos(){
      const emailUsuario = this.usuarioService.obtenerEmailUsuarioLogeado();
      this.misComprasService.obtenerComprasUsuario(emailUsuario).subscribe(
        (compra : any) => {

          if (compra && compra.length > 0) {
            const primeraCompra = compra[0];
            const ultimaCompra = compra[compra.length - 1];

            if (primeraCompra.productos.length > 0) {
              this.primerProducto = primeraCompra.productos[0].nombreProd;
            }

            if (ultimaCompra.productos.length > 0) {
              this.ultimoProducto = ultimaCompra.productos[ultimaCompra.productos.length - 1].nombreProd;
            }
          }

        });
    }

}




<button (click)="recogerProductos()"> recoger productos </button>

<p>Primer producto de la primera compra: {{ primerProducto }}</p>
<p>Último producto de la última compra: {{ ultimoProducto }}</p>
